'use strict';

/**
 * SlidingWindowRateLimiter
 *
 * Implements an exact sliding-window rate limiter with millisecond-bucketed logs.
 * Generated by Claude 3.7 Sonnet (Tier 3) - Bug fixed via AI Self-Improving Loop
 */
class SlidingWindowRateLimiter {
  constructor(options = {}) {
    const { limit, windowMs, maxQueueSize = Infinity } = options;

    if (!Number.isFinite(limit) || limit <= 0) {
      throw new TypeError('options.limit must be a positive finite number');
    }
    if (!Number.isFinite(windowMs) || windowMs <= 0) {
      throw new TypeError('options.windowMs must be a positive finite number');
    }
    if (maxQueueSize !== Infinity && (!Number.isFinite(maxQueueSize) || maxQueueSize < 0)) {
      throw new TypeError('options.maxQueueSize must be a non-negative number or Infinity');
    }

    this.limit = limit;
    this.windowMs = windowMs;
    this.maxQueueSize = maxQueueSize;

    this._buckets = new Map();
    this._totalTokens = 0;
    this._queue = [];
    this._processTimer = null;

    this._gcTimer = setInterval(() => this._purge(), Math.max(1000, Math.ceil(windowMs / 10)));
    if (typeof this._gcTimer.unref === 'function') this._gcTimer.unref();
  }

  _purge(now = Date.now()) {
    const threshold = now - this.windowMs;
    for (const [ts, count] of this._buckets) {
      if (ts > threshold) break;
      this._totalTokens -= count;
      this._buckets.delete(ts);
    }
  }

  _record(now, tokens) {
    this._buckets.set(now, (this._buckets.get(now) || 0) + tokens);
    this._totalTokens += tokens;
  }

  tryAcquire(tokens = 1) {
    if (!Number.isFinite(tokens) || tokens <= 0) {
      throw new TypeError('tokens must be a positive number');
    }

    const now = Date.now();
    this._purge(now);

    if (this._totalTokens + tokens > this.limit) {
      return false;
    }

    this._record(now, tokens);
    return true;
  }

  getRemainingTokens() {
    this._purge(Date.now());
    return Math.max(0, this.limit - this._totalTokens);
  }

  acquire(tokens = 1, timeoutMs = 5000) {
    return new Promise((resolve, reject) => {
      if (!Number.isFinite(tokens) || tokens <= 0) {
        reject(new TypeError('tokens must be a positive number'));
        return;
      }
      if (tokens > this.limit) {
        reject(new Error(`Requested tokens (${tokens}) exceed the limiter's capacity (${this.limit})`));
        return;
      }

      if (this.tryAcquire(tokens)) {
        resolve();
        return;
      }

      if (this._queue.length >= this.maxQueueSize) {
        reject(new Error('SlidingWindowRateLimiter queue is full'));
        return;
      }

      const entry = { tokens, resolve, reject, timer: null };
      entry.timer = setTimeout(() => {
        this._removeFromQueue(entry);
        reject(new Error(`Timed out after ${timeoutMs}ms waiting to acquire ${tokens} token(s)`));
        this._runQueue();
      }, timeoutMs);
      if (typeof entry.timer.unref === 'function') entry.timer.unref();

      this._queue.push(entry);
      this._runQueue();
    });
  }

  _removeFromQueue(entry) {
    const idx = this._queue.indexOf(entry);
    if (idx !== -1) this._queue.splice(idx, 1);
  }

  _runQueue() {
    if (this._processTimer) {
      clearTimeout(this._processTimer);
      this._processTimer = null;
    }

    if (this._queue.length === 0) return;

    const now = Date.now();
    this._purge(now);

    while (this._queue.length > 0) {
      const front = this._queue[0];
      if (this._totalTokens + front.tokens > this.limit) break;

      this._queue.shift();
      clearTimeout(front.timer);
      this._record(Date.now(), front.tokens);
      front.resolve();
    }

    if (this._queue.length > 0) {
      const earliestTs = this._buckets.keys().next().value;
      const delay = earliestTs === undefined
        ? Math.max(1, Math.ceil(this.windowMs / 10))
        : Math.max(1, (earliestTs + this.windowMs) - Date.now());

      // Intentionally NOT unref()'d: while the queue is non-empty there are
      // pending acquire() promises depending on this timer to ever settle.
      this._processTimer = setTimeout(() => {
        this._processTimer = null;
        this._runQueue();
      }, delay);
    }
  }

  destroy() {
    clearInterval(this._gcTimer);
    if (this._processTimer) clearTimeout(this._processTimer);
    for (const entry of this._queue.splice(0)) {
      clearTimeout(entry.timer);
      entry.reject(new Error('SlidingWindowRateLimiter was destroyed'));
    }
  }
}

module.exports = SlidingWindowRateLimiter;
